import { useState } from 'react';
import {
  JxSegmentedControl,
  JxSlider,
  JxSwitch,
  JxSelect,
  JxDivider,
  JxBadge,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';
type Font = 'system' | 'serif' | 'mono';

interface AppearanceSettingsValue {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: Font;
}

interface AppearanceSettingsProps {
  defaultValue?: Partial<AppearanceSettingsValue>;
  onChange?: (value: AppearanceSettingsValue) => void;
}

const THEME_LABELS: Record<Theme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

export default function AppearanceSettings({
  defaultValue,
  onChange,
}: AppearanceSettingsProps) {
  const [theme, setTheme] = useState<Theme>(defaultValue?.theme ?? 'system');
  const [scale, setScale] = useState<number>(defaultValue?.scale ?? 100);
  const [dense, setDense] = useState<boolean>(defaultValue?.dense ?? false);
  const [font, setFont] = useState<Font>(defaultValue?.font ?? 'system');

  const emit = (next: Partial<AppearanceSettingsValue>) => {
    const merged: AppearanceSettingsValue = {
      theme,
      scale,
      dense,
      font,
      ...next,
    };
    onChange?.(merged);
  };

  return (
    <div
      className="jx-panel"
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-6)',
        padding: 'var(--jx-space-6)',
      }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-3)',
        }}
      >
        <h2 className="jx-heading">Внешний вид</h2>
        <JxBadge variant="neutral">{THEME_LABELS[theme]}</JxBadge>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
        <span className="jx-label">Тема</span>
        <JxSegmentedControl
          value={theme}
          onValueChange={(value) => {
            const next = value as Theme;
            setTheme(next);
            emit({ theme: next });
          }}
          options={[
            { value: 'light', label: 'Светлая' },
            { value: 'dark', label: 'Тёмная' },
            { value: 'system', label: 'Системная' },
          ]}
        />
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
          }}
        >
          <span className="jx-label">Масштаб интерфейса</span>
          <span className="jx-text-muted">{scale}%</span>
        </div>
        <JxSlider
          min={80}
          max={140}
          step={5}
          value={scale}
          onValueChange={(value) => {
            const next = value as number;
            setScale(next);
            emit({ scale: next });
          }}
        />
      </div>

      <JxSwitch
        value={dense}
        onValueChange={(value) => {
          const next = value as boolean;
          setDense(next);
          emit({ dense: next });
        }}
      >
        Плотная вёрстка
      </JxSwitch>

      <JxDivider />

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-3)' }}>
        <span className="jx-heading-sm">Ещё</span>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
          <span className="jx-label">Шрифт</span>
          <JxSelect
            value={font}
            onValueChange={(value) => {
              const next = value as Font;
              setFont(next);
              emit({ font: next });
            }}
            options={[
              { value: 'system', label: 'Системный' },
              { value: 'serif', label: 'Serif' },
              { value: 'mono', label: 'Моноширинный' },
            ]}
          />
        </div>
      </div>
    </div>
  );
}

